import{_ as i,o as s,c as a,ai as d}from"./chunks/framework.BI5prboT.js";const k=JSON.parse('{"title":"方案 A 和方案 B 差在哪","description":"","frontmatter":{},"headers":[],"relativePath":"basis/hybrid/jsbridge-compare.md","filePath":"basis/hybrid/jsbridge-compare.md"}'),e={name:"basis/hybrid/jsbridge-compare.md"};function r(o,t,p,l,n,h){return s(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="方案-a-和方案-b-差在哪" tabindex="-1">方案 A 和方案 B 差在哪 <a class="header-anchor" href="#方案-a-和方案-b-差在哪" aria-label="Permalink to &quot;方案 A 和方案 B 差在哪&quot;">​</a></h1><p>两套桥做同一件事：网页请 App 帮忙，App 做完再告诉网页。</p><p>不同的是传话方式。</p><ul><li><a href="./jsbridge-a.html">方案 A：只用一个通道</a></li><li><a href="./jsbridge-b.html">方案 B：一个能力一个通道</a></li><li><a href="./JSBridge.html">JSBridge 原理</a></li></ul><p>完整实现见各自文末源码，这里不重复贴。</p><hr><h2 id="核心差别就一句" tabindex="-1">核心差别就一句 <a class="header-anchor" href="#核心差别就一句" aria-label="Permalink to &quot;核心差别就一句&quot;">​</a></h2><p><strong>A：所有请求进同一个 <code>JSBridge</code>，做什么写在 <code>path</code> 上。</strong><br><strong>B：能力名就是通道名，登录走登录、分享走分享。</strong></p><p>登录在两边长这样：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// A</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nativeApp.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">callNative</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app://login&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {}, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {});</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// B</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendToApp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;login&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {}, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {});</span></span></code></pre></div><p>网页想做的事一样。A 把 <code>login</code> 写在字符串里丢进总入口；B 去名叫 <code>login</code> 的入口。</p><p>两边都会发一个 id（A 叫 <code>callbackId</code>，B 叫 <code>__token</code>），否则同时两次调用会对错单。App 做完都是在网页里执行一句 JS，按 id 找回当初那次请求。</p><hr><h2 id="对照" tabindex="-1">对照 <a class="header-anchor" href="#对照" aria-label="Permalink to &quot;对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>A</th><th>B</th></tr></thead><tbody><tr><td>入口数量</td><td>始终 1 个 <code>JSBridge</code></td><td>有几个能力就有几个</td></tr><tr><td>怎么表达「做什么」</td><td><code>path: &#39;app://login&#39;</code></td><td>通道名 <code>login</code></td></tr><tr><td>对单</td><td><code>callbackId</code></td><td><code>__token</code></td></tr><tr><td>网页怎么等结果</td><td>回调函数（业务常再包 Promise）</td><td>直接返回 Promise</td></tr><tr><td>反复通知（键盘）</td><td>同一回调 <code>keepAlive</code></td><td>用广播 <code>on</code></td></tr><tr><td>App 主动推（主题）</td><td>SDK 没单独做</td><td><code>trigger</code> / <code>on</code></td></tr><tr><td>iPhone / 安卓</td><td>SDK 内部收成同一套</td><td>JS 里按端分支</td></tr><tr><td>能力不存在</td><td>发出去才知道</td><td>找通道时立刻报错</td></tr><tr><td>电脑浏览器</td><td>可能 <code>history.back()</code></td><td><code>reject(&#39;noMobile&#39;)</code></td></tr><tr><td>加新能力</td><td>App 多认一种 path</td><td>三端都要加同名通道</td></tr><tr><td>本地假数据</td><td>一般自己在业务层 mock</td><td>URL <code>isMockAPP</code></td></tr></tbody></table><hr><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><p>A 更省事：App 只维护一个入口，双端对网页长一样，能力再多也不涨注入点。短处是 <code>path</code> 写错只能运行时发现，没有现成的 App→网页广播，浏览器调试时找不到桥会往回退。</p><p>B 更直白：通道名就是功能名，能 <code>await</code>，请求和广播分开，缺通道立刻报错。短处是每加一个能力，iPhone / 安卓 / Flutter 都要开新通道；等回包没有超时；<code>clear</code> 只能清空某一事件的全部听众。</p><p>常见取舍：</p><ul><li>能力会很多，不想开一堆入口 → <strong>A</strong></li><li>主题、登录态等 App 经常主动推 → <strong>B</strong></li><li>页面大量 <code>await</code> → <strong>B</strong>，或 A 外包一层 Promise</li><li>同一页要嵌多个 App 并在浏览器可开 → <strong>A 那种再包一层环境判断</strong></li><li>电脑上先跑通流程 → <strong>B 的 <code>isMockAPP</code> 更现成</strong></li></ul><p>从零做，比较稳的拼法：底下用 A（一个 <code>JSBridge</code> + <code>path</code>），面上用 B 的用法（Promise + <code>on</code>）。按这个拼好的实现见 <a href="./jsbridge-better.html">一套更好用的 JSBridge</a>。</p>`,22)])])}const g=i(e,[["render",r]]);export{k as __pageData,g as default};
